//! Frozen protobuf frames encoded by the oldest supported release.
//!
//! Generated by building stargate v0.19.2
//! (d12dd96dfbefb63c7c405baa0d1feba4e14f397b) and encoding the values asserted
//! below with that release's generated types. v0.19.1 produced identical bytes.
//! Do not regenerate these from the candidate schema: the released wire
//! contract is the fixture. Add fixtures for newer releases beside these; retire
//! a release's fixtures only after it leaves the support window and every
//! retained-release obligation for it has closed.

use std::collections::HashMap;

use prost::Message;

use crate::pb::{
    InferenceServerAck, InferenceServerRegistration, InferenceServerStatus, WatchStargatesResponse,
};

const V0_19_2_REGISTRATION: &str = concat!(
    "0a0770796c6f6e2d611a660a0c636f6d7061742d6d6f64656c12560a520900000000000059401100",
    "00000000002940180120402900000000000049403080203880084080184802500858800162021019",
    "680170017880d8c1a28c348201086b765f63616368658a0106656e67696e65100120012a09636c75",
    "737465722d61",
);
const V0_19_2_ACK: &str = concat!(
    "0a1773746172676174652d302e6578616d706c653a373434331a0e3132372e302e302e313a373434",
    "33",
);
const V0_19_2_WATCH: &str = concat!(
    "0a500a0a73746172676174652d30121873746172676174652d302e6578616d706c653a3530303531",
    "1a1773746172676174652d302e6578616d706c653a38303830220f3132372e302e302e313a353030",
    "35311224687474703a2f2f73746172676174652d72656d6f74652e6578616d706c653a3530303531",
);

fn bytes(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&hex[index..index + 2], 16).unwrap())
        .collect()
}

/// A Pylon registration from the oldest supported release decodes with every
/// field intact, and the current types re-encode it byte for byte. Current
/// producers therefore send the same frame for the same values, and current
/// consumers read released frames without loss.
#[test]
fn released_pylon_registration_round_trips() {
    let frame = bytes(V0_19_2_REGISTRATION);
    let registration = InferenceServerRegistration::decode(frame.as_slice()).unwrap();
    assert_eq!(registration.inference_server_id, "pylon-a");
    assert_eq!(registration.inference_server_url, "");
    assert!(registration.reverse_tunnel);
    assert_eq!(registration.cluster_id, "cluster-a");
    let model = &registration.models["compat-model"];
    assert_eq!(model.status, InferenceServerStatus::Active as i32);
    let stats = model.stats.as_ref().unwrap();
    assert_eq!(stats.last_mean_input_tps, 100.0);
    assert_eq!(stats.output_tps, 12.5);
    assert_eq!(stats.queue_size, 1);
    assert_eq!(stats.queued_input_size, 64);
    assert_eq!(stats.max_output_tps, 50.0);
    assert_eq!(stats.kv_cache_capacity_tokens, 4096);
    assert_eq!(stats.kv_cache_used_tokens, 1024);
    assert_eq!(stats.kv_cache_free_tokens, 3072);
    assert_eq!(stats.num_running_queries, 2);
    assert_eq!(stats.max_engine_concurrency, 8);
    assert_eq!(stats.total_query_input_size, 128);
    assert_eq!(
        stats.queue_time_estimate_ms_by_priority,
        HashMap::from([(0, 25)])
    );
    assert_eq!(stats.input_processing_queries, 1);
    assert_eq!(stats.output_generation_queries, 1);
    assert_eq!(stats.stats_observed_at_unix_ms, 1_790_000_000_000);
    assert_eq!(stats.stats_capabilities, ["kv_cache"]);
    assert_eq!(stats.stats_sources, ["engine"]);
    // Fields added after this release stay absent.
    assert_eq!(stats.max_input_tps, None);
    assert_eq!(registration.encode_to_vec(), frame);
}

/// Stargate responses from the oldest supported release decode in current
/// Pylons, and the current types re-encode them byte for byte, so released
/// Pylons read current Stargate responses for the same values.
#[test]
fn released_stargate_responses_round_trip() {
    let frame = bytes(V0_19_2_ACK);
    let ack = InferenceServerAck::decode(frame.as_slice()).unwrap();
    assert_eq!(ack.reverse_tunnel_target, "stargate-0.example:7443");
    assert_eq!(ack.reverse_tunnel_pylon_dial_addr, "127.0.0.1:7443");
    assert_eq!(ack.encode_to_vec(), frame);

    let frame = bytes(V0_19_2_WATCH);
    let watch = WatchStargatesResponse::decode(frame.as_slice()).unwrap();
    let [stargate] = watch.stargates.as_slice() else {
        panic!("expected one Stargate: {watch:?}");
    };
    assert_eq!(stargate.stargate_id, "stargate-0");
    assert_eq!(stargate.advertise_addr, "stargate-0.example:50051");
    assert_eq!(stargate.http_advertise_addr, "stargate-0.example:8080");
    assert_eq!(stargate.grpc_pylon_dial_addr, "127.0.0.1:50051");
    assert_eq!(
        watch.watch_stargate_urls,
        ["http://stargate-remote.example:50051"]
    );
    assert_eq!(watch.encode_to_vec(), frame);
}
